#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);long long s=0;
for(int i=0;i<n;++i)for(int j=0;j<n;++j){long long x;scanf("%lld",&x);
if(i==j)s+=x; if(i+j==n-1&&i!=j)s+=x;}
printf("%lld\n",s);return 0;}

